CREATE TABLE public.volunteer_signups("id" uuid DEFAULT gen_random_uuid() NOT NULL,"production_id" uuid,"portal_token" uuid DEFAULT gen_random_uuid() NOT NULL,"shift_date" date,"shift_start_time" time,"shift_end_time" time,"approved_hours" numeric,"discount_requested" bool DEFAULT false,"created_at" timestamptz DEFAULT now(),"portal_invite_sent_at" timestamptz,"no_email" bool DEFAULT false,"name" text NOT NULL,"email" text,"phone" text,"notes" text,"status" text DEFAULT 'pending'::text,"role_name" text,"department" text,"discount_performer" text,"check_in_with" text,"first_name" text,"last_name" text,"volunteer_name" text,"volunteer_email" text,"message" text,"required_dates" text[] DEFAULT '{}'::text[],"volunteer_passcode" text,PRIMARY KEY(id));
ALTER TABLE public.volunteer_signups ENABLE ROW LEVEL SECURITY;
GRANT ALL ON public.volunteer_signups TO anon,authenticated;
CREATE POLICY legacy_public_volunteers ON public.volunteer_signups FOR ALL USING(true) WITH CHECK(true);
